ALTER TABLE employees ALTER COLUMN email DROP NOT NULL;
ALTER TABLE employees ADD COLUMN employee_code text;
UPDATE employees SET employee_code='E-' || substring(replace(id::text,'-','') from 1 for 12);
ALTER TABLE employees ALTER COLUMN employee_code SET NOT NULL;
ALTER TABLE employees ALTER COLUMN employee_code SET DEFAULT ('E-' || substring(replace(gen_random_uuid()::text,'-','') from 1 for 12));
ALTER TABLE employees ADD CONSTRAINT employee_store_code UNIQUE(store_id,employee_code);
ALTER TABLE employees ADD COLUMN pin_hash text;
ALTER TABLE products ADD COLUMN tax_rate numeric(5,2) NOT NULL DEFAULT 0 CHECK(tax_rate>=0 AND tax_rate<=100);
UPDATE roles SET permissions=permissions || '["team.manage","pos.access","sales.read","discount.approve","shift.approve","cash.manage"]'::jsonb WHERE name='Owner';
UPDATE roles SET permissions=permissions || '["pos.access","sales.read","discount.approve","shift.approve","cash.manage"]'::jsonb WHERE name='Manager';
UPDATE roles SET permissions=permissions || '["pos.access"]'::jsonb WHERE name='Cashier';
CREATE TABLE pos_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text NOT NULL UNIQUE,device_id uuid NOT NULL REFERENCES devices,employee_id uuid NOT NULL REFERENCES employees,expires_at timestamptz NOT NULL);
CREATE UNIQUE INDEX pos_one_operator ON pos_sessions(device_id);
CREATE TABLE pin_attempts(device_id uuid PRIMARY KEY REFERENCES devices,failures integer NOT NULL DEFAULT 0,locked_until timestamptz);
CREATE TABLE shifts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES stores,device_id uuid NOT NULL,employee_id uuid NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')),opening_cash numeric(14,2) NOT NULL CHECK(opening_cash>=0),expected_cash numeric(14,2),counted_cash numeric(14,2),difference numeric(14,2),opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,notes text NOT NULL DEFAULT '',request_id uuid NOT NULL,request_hash text NOT NULL,close_request_id uuid,close_hash text,approver_id uuid,UNIQUE(store_id,request_id),UNIQUE(id,store_id),FOREIGN KEY(device_id,store_id) REFERENCES devices(id,store_id),FOREIGN KEY(employee_id,store_id) REFERENCES employees(id,store_id),FOREIGN KEY(approver_id,store_id) REFERENCES employees(id,store_id));
CREATE UNIQUE INDEX shift_one_open_device ON shifts(device_id) WHERE status='open';
CREATE UNIQUE INDEX shift_one_open_employee ON shifts(employee_id) WHERE status='open';
CREATE SEQUENCE receipt_sequence;
CREATE TABLE sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES stores,device_id uuid NOT NULL,employee_id uuid NOT NULL,shift_id uuid NOT NULL,request_id uuid NOT NULL,request_hash text NOT NULL,receipt_number text NOT NULL,total numeric(14,2) NOT NULL CHECK(total>=0),tax numeric(14,2) NOT NULL CHECK(tax>=0),discount numeric(14,2) NOT NULL CHECK(discount>=0),receipt jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(store_id,request_id),UNIQUE(store_id,receipt_number),UNIQUE(id,store_id),FOREIGN KEY(device_id,store_id) REFERENCES devices(id,store_id),FOREIGN KEY(employee_id,store_id) REFERENCES employees(id,store_id),FOREIGN KEY(shift_id,store_id) REFERENCES shifts(id,store_id));
CREATE TABLE sale_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES stores,sale_id uuid NOT NULL,product_id uuid NOT NULL,quantity numeric(15,3) NOT NULL CHECK(quantity>0),price numeric(14,2) NOT NULL,cost numeric(14,2) NOT NULL,tax_rate numeric(5,2) NOT NULL,total numeric(14,2) NOT NULL,FOREIGN KEY(sale_id,store_id) REFERENCES sales(id,store_id),FOREIGN KEY(product_id,store_id) REFERENCES products(id,store_id));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES stores,sale_id uuid NOT NULL,method text NOT NULL CHECK(method IN ('cash','card')),amount numeric(14,2) NOT NULL CHECK(amount>=0),tendered numeric(14,2) NOT NULL CHECK(tendered>=0),change numeric(14,2) NOT NULL CHECK(change>=0),FOREIGN KEY(sale_id,store_id) REFERENCES sales(id,store_id));
CREATE TABLE cash_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES stores,shift_id uuid NOT NULL,employee_id uuid NOT NULL,device_id uuid NOT NULL,amount numeric(14,2) NOT NULL,kind text NOT NULL CHECK(kind IN ('opening','sale','in','out')),reason text NOT NULL,request_id uuid NOT NULL,request_hash text NOT NULL,sale_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(store_id,request_id),FOREIGN KEY(shift_id,store_id) REFERENCES shifts(id,store_id),FOREIGN KEY(employee_id,store_id) REFERENCES employees(id,store_id),FOREIGN KEY(device_id,store_id) REFERENCES devices(id,store_id),FOREIGN KEY(sale_id,store_id) REFERENCES sales(id,store_id));
ALTER TABLE movements ADD COLUMN sale_id uuid;
ALTER TABLE movements ADD COLUMN shift_id uuid;
ALTER TABLE movements ADD CONSTRAINT movement_sale_store FOREIGN KEY(sale_id,store_id) REFERENCES sales(id,store_id);
ALTER TABLE movements ADD CONSTRAINT movement_shift_store FOREIGN KEY(shift_id,store_id) REFERENCES shifts(id,store_id);
CREATE INDEX sales_store_date ON sales(store_id,created_at DESC);
CREATE INDEX cash_shift ON cash_movements(shift_id);
CREATE TRIGGER immutable_sales BEFORE UPDATE OR DELETE ON sales FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_sale_items BEFORE UPDATE OR DELETE ON sale_items FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_payments BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_cash BEFORE UPDATE OR DELETE ON cash_movements FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE FUNCTION prevent_closed_shift_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='closed' THEN RAISE EXCEPTION 'Closed shifts are immutable'; END IF; IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Shifts cannot be deleted'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_closed_shift BEFORE UPDATE OR DELETE ON shifts FOR EACH ROW EXECUTE FUNCTION prevent_closed_shift_mutation();
